from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    m = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    # Build Aho-Corasick trie
    children: list[list[int]] = [[-1] * m]
    is_bad: list[bool] = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            if children[node][c] == -1:
                children[node][c] = len(children)
                children.append([-1] * m)
                is_bad.append(False)
            node = children[node][c]
        is_bad[node] = True

    # Build failure links and full transition table
    num_nodes = len(children)
    fail = [0] * num_nodes
    q: deque[int] = deque()

    for c in range(m):
        nxt = children[0][c]
        if nxt != -1:
            fail[nxt] = 0
            q.append(nxt)
        else:
            children[0][c] = 0

    while q:
        u = q.popleft()
        if is_bad[fail[u]]:
            is_bad[u] = True
        for c in range(m):
            v = children[u][c]
            if v != -1:
                fail[v] = children[fail[u]][c]
                q.append(v)
            else:
                children[u][c] = children[fail[u]][c]

    # Compress to good (non-banned) states
    good_idx = [-1] * num_nodes
    good_states: list[int] = []
    for u in range(num_nodes):
        if not is_bad[u]:
            good_idx[u] = len(good_states)
            good_states.append(u)

    k = len(good_states)
    mat = [[0] * k for _ in range(k)]
    for i, u in enumerate(good_states):
        for c in range(m):
            v = children[u][c]
            j = good_idx[v]
            if j != -1:
                mat[i][j] += 1

    # Matrix exponentiation: compute vec * mat^n where vec = [1, 0, ..., 0]
    vec = [0] * k
    vec[0] = 1

    while n > 0:
        if n & 1:
            nxt_vec = [0] * k
            for i in range(k):
                vi = vec[i]
                if vi:
                    row = mat[i]
                    for j in range(k):
                        nxt_vec[j] = (nxt_vec[j] + vi * row[j]) % MOD
            vec = nxt_vec
        n >>= 1
        if n > 0:
            nxt_mat = [[0] * k for _ in range(k)]
            for i in range(k):
                row_i = mat[i]
                res_row = nxt_mat[i]
                for p in range(k):
                    aip = row_i[p]
                    if aip:
                        row_p = mat[p]
                        for j in range(k):
                            res_row[j] += aip * row_p[j]
                for j in range(k):
                    res_row[j] %= MOD
            mat = nxt_mat

    return sum(vec) % MOD
